SELECT ?item ?codata ?en ?sv (GROUP_CONCAT(DISTINCT ?sym; separator=" | ") AS ?syms) (GROUP_CONCAT(DISTINCT STR(?num); separator=" | ") AS ?nums) WHERE {
  ?item wdt:P1645 ?codata .
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item wdt:P416 ?sym }
  OPTIONAL { ?item wdt:P1181 ?num }
} GROUP BY ?item ?codata ?en ?sv ORDER BY ?codata

